def toterminal(self, tw: TerminalWriter) -> None:
    if self.args:
        linesofar = ""
        for name, value in self.args:
            ns = f"{name} = {value}"
            if len(ns) + len(linesofar) + 2 > tw.fullwidth:
                if linesofar:
                    tw.line(linesofar)
                linesofar = ns
            else:
                if linesofar:
                    linesofar += ", " + ns
                else:
                    linesofar = ns
        if linesofar:
            tw.line(linesofar)
        tw.line("")

