def elapsed(self) -> Duration:
    """Measure the duration since `Instant` was created."""
    return Duration(start=self, stop=Instant())

def repr(self, class_name: str) -> str:
    return "<{} {} _old={} _state={!r} tmpfile={!r}>".format(
        class_name,
        self.name,
        (hasattr(self, "_old") and repr(self._old)) or "<UNSET>",
        self._state,
        self.tmpfile,
    )

def repr(self, object: object) -> str:
    """Return a 'safe' (non-recursive, one-line) string repr for 'object'."""
    return saferepr(object)

def repr(self, x: object) -> str:
    try:
        if self.use_ascii:
            s = ascii(x)
        else:
            s = super().repr(x)
    except (KeyboardInterrupt, SystemExit):
        raise
    except BaseException as exc:
        s = _format_repr_exception(exc, x)
    if self.maxsize is not None:
        s = _ellipsize(s, self.maxsize)
    return s

def pytest_make_collect_report(
    self, collector: nodes.Collector
) -> CollectReport | None:
    if isinstance(collector, File):
        if collector.path not in self.lfplugin._last_failed_paths:
            self.lfplugin._skipped_files += 1

            return CollectReport(
                collector.nodeid, "passed", longrepr=None, result=[]
            )
    return None

def pytest_make_collect_report(
    self, collector: Collector
) -> Generator[None, CollectReport, CollectReport]:
    if isinstance(collector, File):
        self.resume_global_capture()
        try:
            rep = yield
        finally:
            self.suspend_global_capture()
        out, err = self.read_global_capture()
        if out:
            rep.sections.append(("Captured stdout", out))
        if err:
            rep.sections.append(("Captured stderr", err))
    else:
        rep = yield
    return rep

def pytest_make_collect_report(
    self, collector: nodes.Collector
) -> Generator[None, CollectReport, CollectReport]:
    result = yield
    if isinstance(collector, nodes.Directory):
        plugin = self._pending_conftests.pop(collector.path, None)
        if plugin is not None:
            self.parsefactories(holder=plugin, node=collector)
    return result

